def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((agent_id, opp))

    if len(alive) == 0:
        base = DAILY_SALARY * 0.35
        if hp <= 2 or no_water_days >= 1:
            base = DAILY_SALARY * 0.75
        return float(max(0.0, min(budget, base)))

    prev_bids = []
    threat_bid = 0.0
    eric_bid = None
    urgent_opponents = 0

    for agent_id, opp in alive:
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
            urgent_opponents += 1
        prev = opp.get('previous_trace') or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if float(bid) > threat_bid:
                threat_bid = float(bid)
            if agent_id == 'Eric':
                eric_bid = float(bid)

    if eric_bid is None:
        eric_bid = 99.0

    slots = int(supply // WATER_REQ)
    if slots < 1:
        slots = 1

    contested = slots <= len(alive)
    very_tight = slots <= 1
    high_supply = supply >= 24

    bid = DAILY_SALARY * 0.45

    if hp <= 2 or no_water_days >= 2:
        bid = max(bid, min(130.0, eric_bid + 2.5, budget))
    elif no_water_days >= 1:
        if very_tight:
            bid = max(bid, min(122.0, eric_bid + 1.0, budget))
        else:
            bid = max(bid, DAILY_SALARY * 0.85)
    else:
        if very_tight:
            if hp >= 5 and budget < 500:
                bid = DAILY_SALARY * 0.18
            else:
                target = max(threat_bid + 1.5, eric_bid + 0.5)
                if target >= 95:
                    if hp >= 5:
                        bid = DAILY_SALARY * 0.22
                    else:
                        bid = min(116.0, target)
                else:
                    bid = min(105.0, max(DAILY_SALARY * 0.72, target))
        else:
            if high_supply and hp >= 4:
                bid = DAILY_SALARY * 0.28
            else:
                target = max(DAILY_SALARY * 0.52, threat_bid * 0.72)
                if urgent_opponents >= 2:
                    target += 6.0
                bid = min(88.0, target)

    if day >= 8:
        if hp <= 3 or no_water_days >= 1:
            bid = max(bid, DAILY_SALARY * 0.9)
        else:
            bid = max(bid, DAILY_SALARY * 0.4)

    if budget < DAILY_SALARY * 2:
        bid = min(bid, max(0.0, budget * 0.7))

    return float(max(0.0, min(budget, bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    # Basic safety: if no budget, bid 0
    budget = float(my_status.get('budget', 0.0))
    hp = int(my_status.get('hp', 0))

    if budget <= 0:
        return 0.0

    # Collect yesterday bids from alive opponents only
    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append(opp)

    yesterday_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    # Estimate opponent pressure level from yesterday
    # If they commonly bid around 100+, they likely compete aggressively today.
    pressure = 0.0
    if yesterday_bids:
        # Use a high quantile proxy without heavy computation
        yesterday_bids_sorted = sorted(yesterday_bids)
        idx = int(0.75 * (len(yesterday_bids_sorted) - 1)) if len(yesterday_bids_sorted) > 1 else 0
        pressure = float(yesterday_bids_sorted[idx])

    # Supply pressure: with supply 15-25, water can be scarce relative to WATER_REQ.
    # If supply is near minimum, competition is higher.
    scarcity = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        scarcity = (float(MAX_SUPPLY) - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
        if scarcity < 0:
            scarcity = 0.0
        if scarcity > 1:
            scarcity = 1.0

    # Target bid logic:
    # - If healthy, bid slightly below yesterday pressure to steal allocation.
    # - If low hp, bid to secure survival.
    # - If no trace data, bid moderate based on scarcity.
    if yesterday_bids:
        # Keep under typical pressure to avoid overpaying, but adjust for scarcity.
        base_target = pressure
        # Undercut amount: larger undercut when supply is comfortable.
        undercut = 8.0 * (0.2 + 0.8 * scarcity)
        target = base_target - undercut

        # If I'm low hp, increase target to ensure allocation.
        if hp <= 2:
            target = base_target + 10.0
        elif hp <= 4:
            target = max(target, base_target - 2.0)

        # Clamp target to reasonable range relative to DAILY_SALARY
        # (yesterday averages near ~80-120 while DAILY_SALARY=150)
        min_bid = DAILY_SALARY * (0.25 + 0.25 * scarcity)
        max_bid = min(budget, DAILY_SALARY * (0.95 if hp <= 2 else 0.75 + 0.15 * scarcity))
        bid = min(max(target, min_bid), max_bid)
        return float(bid)

    # No yesterday bids: fallback
    # If hp is critical, bid aggressively.
    if hp <= 2:
        return float(min(budget, DAILY_SALARY * 0.9))
    if hp <= 4:
        return float(min(budget, DAILY_SALARY * (0.65 + 0.2 * scarcity)))

    # Otherwise bid moderate, higher when supply is scarce.
    return float(min(budget, DAILY_SALARY * (0.45 + 0.25 * scarcity)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    avg_prev = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 50.0

    if my_status['hp'] <= 3:
        bid = min(my_status['budget'], max(avg_prev * 1.2, 90.0))
    else:
        bid = min(my_status['budget'], max(avg_prev * 0.95, 45.0))

    return float(bid)
